"    // Timer for initial loading splash screen (acts as fallback; splashWindow itself triggers app-ready upon animation end)
    const timer = setTimeout(() => {
      setShowInitialSplash(false);
      try {
        const { ipcRenderer } = window.require('electron');
        ipcRenderer.send('app-ready');
      } catch (e) {
        // Safe fallback if not running inside Electron
      }
    }, 7500);"

